def normshape(p,trans=False):
 pts=list(p); variants=[]
 for rot in range(8 if trans else 1):
  q=[]
  for y,x in pts:
   if rot==0: yy,xx=y,x
   elif rot==1: yy,xx=y,-x
   elif rot==2: yy,xx=-y,x
   elif rot==3: yy,xx=-y,-x
   elif rot==4: yy,xx=x,y
   elif rot==5: yy,xx=x,-y
   elif rot==6: yy,xx=-x,y
   else: yy,xx=-x,-y
