def parsegrid(txt, label):
 m=re.search(label+r' \((\d+)x(\d+)\):\n((?:[0-9 ]+\n?)+)',txt)
 return [list(map(int,x.split())) for x in m.group(3).strip().splitlines()] if m else None
def cc(g,bg):
 H,W=len(g),len(g[0]); seen=set(); out=[]
 for i in range(H):
  for j in range(W):
   v=g[i][j]
   if v==bg or (i,j) in seen:continue
   q=[(i,j)];seen.add((i,j));p=[]
   while q:
    a,b=q.pop();p.append((a,b))
    for x,y in ((a+1,b),(a-1,b),(a,b+1),(a,b-1)):
     if 0<=x<H and 0<=y<W and (x,y) not in seen and g[x][y]==v:seen.add((x,y));q.append((x,y))
   out.append((v,p))
 return out
